ops.body:
{
  "status": "proposal_not_implemented",
  "owner_choice": "Keep eight workers per root; focus on cache and IO changes",
  "constraints": [
    "Preserve foreground hook semantics and concurrency",
    "Preserve all agent sessions, supervisors, and their jobs",
    "Change background work admission and cache reuse, not session lifecycle"
  ],
  "verified_versions": {
    "capt_hook": "12.93.2",
    "cc_transcript": "14.40.1",
    "ccx_cleanup": "v0.78.8"
  },
  "context": {
    "repeated_recovery": "Captain Hook recycle and deletion queue pause restore headroom temporarily",
    "evidence_files": [
      "recovery-result.json",
      "durable-baseline-status.json",
      "snapshot-durable-findings.json",
      "cleanup-durable-findings.json",
      "worker-durable-findings.json"
    ]
  },
  "approach": [
    {
      "id": "A",
      "change": "Cleanup awaited-job priority obeys protective caps; pacing charges elapsed metadata work; governor observes calibrated host IO pressure and surfaces unavailable signals without silently selecting full speed",
      "files": [
        "internal/cleanup/daemon/engine.go",
        "internal/cleanup/daemon/governor.go",
        "internal/cleanup/native/fsevents_darwin.go"
      ],
      "reuse": "Existing slice budget, rate governor, hysteresis, queue priority and persisted pause"
    },
    {
      "id": "B",
      "change": "One host-wide resumable warm job per active evidence scope; identical demand from eight workers joins that job; source and prepared-cache reads consume one shared background IO budget",
      "files": [
        "captain_hook/worker/service.py",
        "internal/hookd/snapshot_owner.go",
        "rust/crates/core/src/snapshot_prepared_service.rs"
      ],
      "reuse": "RegisteredWarmState cursors, membership revisions, existing warm admission and measured byte counters"
    },
    {
      "id": "C",
      "change": "Primary-driven builtin predicate evaluation with scoped observers so each loaded fact serves multiple demanded predicates; retain existing identical-query cache",
      "files": [
        "captain_hook/dispatch.py",
        "captain_hook/snapshots/client.py",
        "rust/crates/core/src/snapshot_prepared_service.rs"
      ],
      "reuse": "Existing lease/context cache identity, primary traversal, unknown observer outcomes"
    },
    {
      "id": "D",
      "change": "Versioned bounded immutable prepared-fact reuse across owner generations; retain ephemeral leases and private live-owner directories",
      "files": [
        "rust/crates/core/src/snapshot_prepared_disk.rs",
        "rust/crates/core/src/snapshot.rs"
      ],
      "reuse": "PreparedDiskKey source/context identity, payload validation and reservation accounting"
    }
  ],
  "pitfalls": [
    "Cleanup Await bypass is a confirmed source path; it was not proven active during the slowdown",
    "Pause persistence is already implemented; resumption was not proven a bug",
    "Deadline/caller cancellation must not discard shared warm progress or stop another caller work",
    "Observer predicates must preserve lazy primary errors and leave incomplete results unknown",
    "Cache adoption must reject changed source/context/schema and corrupt entries; immutable facts cannot carry old leases",
    "Producer and consumer protocol changes require paired release/pin/schema verification"
  ],
  "schedule": [
    {
      "phase": "A",
      "blocks_on": [],
      "verification": "Deterministic awaited-job throttle, zero-removal slow-slice, sensor-error and hysteresis regressions; live bounded queue run with latency/IO measurements"
    },
    {
      "phase": "B",
      "blocks_on": [],
      "verification": "Eight callers, one advancing job; same/different scope invalidation; deadline progress retention; bounded aggregate source+prepared bytes; foreground hook latency"
    },
    {
      "phase": "C",
      "blocks_on": [],
      "verification": "Exact lazy error and freshness/context cases; positive and negative demand replay; equivalent results with reduced fact reads; paired strict schema CI"
    },
    {
      "phase": "D",
      "blocks_on": [
        "B"
      ],
      "verification": "Validated unchanged facts reused after graceful/crash owner restart; changed/corrupt facts refused; disk/index reconstruction bounds"
    }
  ],
  "execution": "Independent source lanes start A/B/C in isolated worktrees; one shared local build/test slot, at most two workers and host headroom first; D consumes B evidence-scope/invalidation design. CI handles broad suites.",
  "acceptance": "A full representative working day without manual resets or paused-cleanup dependence; unchanged protected session identities, foreground hook correctness/latency, progressing deletion queue, and bounded measured logical/physical IO.",
  "pending": "Proposal only; no source edits, new config, builds, releases or deployment. Primary-observer batching remains a proposal rather than an implicitly selected default."
}
